def fixture(required=1,rejection_rule=FinancialApprovalRejectionRule.ANY_VALID_REJECTION_BLOCKS,rejections_required=None):
 c=MongoClient(os.environ['TEST_VENDOR_MONGO_URI']); db=c['aggregator_'+uuid.uuid4().hex]; v,b,p,d,a=[db[x] for x in ('vendors','vendor_bills','financial_approval_policy_evaluations','financial_approval_decisions','financial_approval_actor_authorizations')]; VendorRegistry.ensure_indexes(v); VendorBillRegistry.ensure_indexes(b); FinancialApprovalPolicyEvaluationRegistry.ensure_indexes(p); FinancialApprovalDecisionRegistry.ensure_indexes(d); FinancialApprovalActorAuthorizationRegistry.ensure_indexes(a); vendor=VendorRegistry.create(VendorIdentity(tenant_id='t',legal_name='V'),v); bill=VendorBill(tenant_id='t',vendor_id=vendor.vendor_id,payable_id='p',gross_amount_minor=100,currency='ZAR',issue_date=date(2026,1,1),due_date=date(2026,2,1),received_at=datetime(2026,1,1,tzinfo=timezone.utc),approval_policy_reference='P'); VendorBillRegistry.create(bill,b); opened=VendorBillRegistry.open_bill('t','p',1,'open',b).vendor_bill; req=FinancialApprovalRequirement('r','CFO',max(required,1)); ev=FinancialApprovalPolicyEvaluation(tenant_id='t',evaluation_id='e',subject_type=FinancialApprovalPolicySubjectType.VENDOR_BILL,subject_id='p',subject_revision=2,approval_policy_reference='P',approval_policy_version='1',approval_required=required>0,approval_requirements=(req,) if required else (),rejection_rule=rejection_rule,rejections_required=rejections_required,subject_snapshot_fingerprint=_compute_vendor_bill_policy_snapshot_fingerprint(opened),evaluator_reference='r',evaluated_at=datetime(2026,1,1,tzinfo=timezone.utc),created_at=datetime(2026,1,1,tzinfo=timezone.utc)); FinancialApprovalPolicyEvaluationRegistry.create(ev,'ek',p); return c,db,p,d,a,ev,opened

def add_evidence(d,a,ev,opened,actor,decision_id,outcome=FinancialApprovalDecisionType.APPROVED,when=datetime(2026,1,1,tzinfo=timezone.utc),requirement_id='r',capacity='CFO',policy_reference='P',policy_version: Optional[str]='1',subject_revision=2,authorized_at=datetime(2026,1,1,tzinfo=timezone.utc),valid_until=None,auth_actor=None,auth_capacity=None,authorization_id=None):
 decision=FinancialApprovalDecision(tenant_id='t',decision_id=decision_id,subject_type=DST.VENDOR_BILL,subject_id='p',decision=outcome,actor_id=actor,actor_capacity=capacity,reason='r',approval_policy_reference=policy_reference,approval_policy_version=policy_version,subject_revision=subject_revision,decided_at=when,created_at=when); auth=FinancialApprovalActorAuthorization(tenant_id='t',authorization_id=authorization_id or 'a-'+decision_id,subject_type=FinancialApprovalPolicySubjectType.VENDOR_BILL,subject_id='p',subject_revision=subject_revision,evaluation_id='e',approval_policy_reference='P',approval_policy_version='1',requirement_id=requirement_id,actor_id=auth_actor or actor,actor_capacity=auth_capacity or capacity,authorization_source_reference='s',authorization_basis_reference='b',authorized_at=authorized_at,valid_until=valid_until,authorization_evidence_fingerprint='a'*128,created_at=when); FinancialApprovalDecisionRegistry.create(decision,'k-'+decision_id,d); FinancialApprovalActorAuthorizationRegistry.create(auth,'ak-'+decision_id,a)

