def test_aggregator_states_and_distinct_quorum_real_mongo():
 c,db,p,d,a,ev,opened=fixture(0); result=FinancialApprovalAggregator(database=db).aggregate('t','e','r0',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.NOT_REQUIRED; c.drop_database(db.name); c.close()
 c,db,p,d,a,ev,opened=fixture(2); add_evidence(d,a,ev,opened,'A','d1'); result=FinancialApprovalAggregator(database=db).aggregate('t','e','r1',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.PENDING and result.requirement_results[0].approvals_counted==1; add_evidence(d,a,ev,opened,'B','d2'); result=FinancialApprovalAggregator(database=db).aggregate('t','e','r2',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.APPROVED and result.source_evidence_fingerprint != ''
 c.drop_database(db.name); c.close()

def test_aggregator_rejection_precedence_and_fingerprint_real_mongo():
 c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','d1'); add_evidence(d,a,ev,opened,'B','reject',FinancialApprovalDecisionType.REJECTED); first=FinancialApprovalAggregator(database=db).aggregate('t','e','r1',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); second=FinancialApprovalAggregator(database=db).aggregate('t','e','r2',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert first.effective_state is FinancialApprovalEffectiveState.REJECTED and first.source_evidence_fingerprint==second.source_evidence_fingerprint; c.drop_database(db.name); c.close()

def test_duplicate_actor_approvals_do_not_inflate_quorum_real_mongo():
 c,db,p,d,a,ev,opened=fixture(2)
 for i in range(3): add_evidence(d,a,ev,opened,'A',f'a{i}',when=datetime(2026,1,1+i,tzinfo=timezone.utc))
 result=FinancialApprovalAggregator(database=db).aggregate('t','e','dup1',datetime(2026,1,5,tzinfo=timezone.utc),datetime(2026,1,5,tzinfo=timezone.utc)); assert result.requirement_results[0].approvals_counted==1 and result.effective_state is FinancialApprovalEffectiveState.PENDING and len(result.requirement_results[0].counted_actor_ids)==1
 add_evidence(d,a,ev,opened,'B','b1',when=datetime(2026,1,4,tzinfo=timezone.utc)); result=FinancialApprovalAggregator(database=db).aggregate('t','e','dup2',datetime(2026,1,5,tzinfo=timezone.utc),datetime(2026,1,5,tzinfo=timezone.utc)); assert result.requirement_results[0].approvals_counted==2 and result.effective_state is FinancialApprovalEffectiveState.APPROVED; c.drop_database(db.name); c.close()

def test_approve_then_reject_latest_decision_wins_real_mongo():
 c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','approved',when=datetime(2026,1,1,tzinfo=timezone.utc)); add_evidence(d,a,ev,opened,'A','rejected',FinancialApprovalDecisionType.REJECTED,datetime(2026,1,2,tzinfo=timezone.utc)); result=FinancialApprovalAggregator(database=db).aggregate('t','e','ar',datetime(2026,1,3,tzinfo=timezone.utc),datetime(2026,1,3,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.REJECTED and 'approved' in [x.decision_id for x in result.excluded_decisions]; c.drop_database(db.name); c.close()

