def test_same_actor_two_lanes_requires_two_distinct_decisions_real_mongo():
 c,db,p,d,a,ev,opened=multi_lane_fixture(); add_evidence(d,a,ev,opened,'A','r1-decision',requirement_id='r1',capacity='CFO'); add_evidence(d,a,ev,opened,'A','r2-decision',requirement_id='r2',capacity='CONTROLLER'); result=FinancialApprovalAggregator(database=db).aggregate('t','e','lanes',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.APPROVED and [r.approvals_counted for r in result.requirement_results]==[1,1]; c.drop_database(db.name); c.close()

def _excluded(result, decision_id, reason):
 assert decision_id not in result.counted_decision_ids
 assert any(x.decision_id == decision_id and x.reason.value == reason for x in result.excluded_decisions)

def test_policy_version_strictness_real_mongo():
 for version, reason in ((None,'POLICY_VERSION_MISSING'),('v1','POLICY_VERSION_MISMATCH')):
  c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','pv',policy_version=version); result=FinancialApprovalAggregator(database=db).aggregate('t','e','pv-'+str(version),datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); _excluded(result,'pv',reason); assert result.effective_state is FinancialApprovalEffectiveState.PENDING; c.drop_database(db.name); c.close()
 c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','pr',policy_reference='policy-X'); result=FinancialApprovalAggregator(database=db).aggregate('t','e','pr',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); _excluded(result,'pr','POLICY_REFERENCE_MISMATCH'); c.drop_database(db.name); c.close()

def test_authorization_time_validity_boundaries_real_mongo():
 t=datetime(2026,1,2,tzinfo=timezone.utc)
 cases=((t+timedelta(days=1),None,'AUTHORIZATION_NOT_YET_VALID'),(t-timedelta(days=1),t-timedelta(seconds=1),'AUTHORIZATION_EXPIRED'))
 for authorized,until,reason in cases:
  c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','time',when=t,authorized_at=authorized,valid_until=until); result=FinancialApprovalAggregator(database=db).aggregate('t','e','time'+reason, t,t); _excluded(result,'time',reason); c.drop_database(db.name); c.close()
 for authorized,until in ((t,t),(t-timedelta(days=1),t),(t-timedelta(days=1),None)):
  c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','valid',when=t,authorized_at=authorized,valid_until=until); result=FinancialApprovalAggregator(database=db).aggregate('t','e','valid'+str(until), t,t); assert result.effective_state is FinancialApprovalEffectiveState.APPROVED and result.requirement_results[0].approvals_counted == 1; c.drop_database(db.name); c.close()

