def test_lane_ambiguity_order_independence_and_wrong_revision_real_mongo():
 for reverse in (False,True):
  c,db,p,d,a,ev,opened=fixture(1); p.delete_many({}); reqs=(FinancialApprovalRequirement('r1','CFO',1),FinancialApprovalRequirement('r2','CFO',1)); ev=FinancialApprovalPolicyEvaluation(tenant_id='t',evaluation_id='e',subject_type=FinancialApprovalPolicySubjectType.VENDOR_BILL,subject_id='p',subject_revision=2,approval_policy_reference='P',approval_policy_version='1',approval_required=True,approval_requirements=reqs,rejection_rule=FinancialApprovalRejectionRule.ANY_VALID_REJECTION_BLOCKS,rejections_required=None,subject_snapshot_fingerprint=_compute_vendor_bill_policy_snapshot_fingerprint(opened),evaluator_reference='r',evaluated_at=datetime(2026,1,1,tzinfo=timezone.utc),created_at=datetime(2026,1,1,tzinfo=timezone.utc)); FinancialApprovalPolicyEvaluationRegistry.create(ev,'ek',p); ids=('r2','r1') if reverse else ('r1','r2'); add_evidence(d,a,ev,opened,'A','amb',requirement_id=ids[0]); add_evidence(d,a,ev,opened,'A','amb2',requirement_id=ids[1]); result=FinancialApprovalAggregator(database=db).aggregate('t','e','amb'+str(reverse),datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert result.effective_state is FinancialApprovalEffectiveState.PENDING and all(r.approvals_counted == 0 for r in result.requirement_results) and any(x.reason.value == 'AMBIGUOUS_REQUIREMENT_MAPPING' for x in result.excluded_decisions); c.drop_database(db.name); c.close()
 c,db,p,d,a,ev,opened=fixture(1); add_evidence(d,a,ev,opened,'A','wrong-rev'); raw=d.find_one({'decision_id':'wrong-rev'}); assert raw is not None; raw['subject_revision']=3; d.replace_one({'decision_id':'wrong-rev'},raw); result=FinancialApprovalAggregator(database=db).aggregate('t','e','wrong-rev',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); _excluded(result,'wrong-rev','WRONG_SUBJECT_REVISION'); c.drop_database(db.name); c.close()

