def test_rejection_evidence_order_is_deterministic_real_mongo():
 c,db,p,d,a,ev,opened=fixture(1,rejection_rule=FinancialApprovalRejectionRule.REJECTION_QUORUM,rejections_required=2); add_evidence(d,a,ev,opened,'B','z-reject',FinancialApprovalDecisionType.REJECTED); add_evidence(d,a,ev,opened,'A','a-reject',FinancialApprovalDecisionType.REJECTED); first=FinancialApprovalAggregator(database=db).aggregate('t','e','order-1',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); second=FinancialApprovalAggregator(database=db).aggregate('t','e','order-2',datetime(2026,1,2,tzinfo=timezone.utc),datetime(2026,1,2,tzinfo=timezone.utc)); assert first.effective_state is FinancialApprovalEffectiveState.REJECTED and first.rejection_actor_ids == ('A','B') and first.rejection_decision_ids == ('a-reject','z-reject') and first.rejection_actor_ids == second.rejection_actor_ids and first.rejection_decision_ids == second.rejection_decision_ids; c.drop_database(db.name); c.close()

